fs-ns2.css:
#fs-ns2 svg.draw{display:block;width:100%;height:auto;overflow:hidden;min-width:34rem}
#fs-ns2 /* chart ink */
.tk{fill:var(--text-muted);font-size:11px;font-family:"InterVar",sans-serif;font-variant-numeric:tabular-nums}
#fs-ns2 .tk-lab{fill:var(--text-secondary);font-size:12px;font-family:"InterVar",sans-serif}
#fs-ns2 .tk-val{fill:var(--text-primary);font-size:13px;font-weight:650;font-family:"InterVar",sans-serif;font-variant-numeric:tabular-nums}
#fs-ns2 .tk-big{fill:var(--text-primary);font-size:22px;font-weight:700;font-family:"InterVar",sans-serif;letter-spacing:-.02em}
#fs-ns2 .gridln{stroke:var(--gridline);stroke-width:1}
#fs-ns2 .axisln{stroke:var(--baseline);stroke-width:1}
#fs-ns2 .zeroln{stroke:var(--rule-strong);stroke-width:1.5}
#fs-ns2 .m-priced{fill:var(--priced)}
#fs-ns2 .m-harm{fill:var(--harm)}
#fs-ns2 .m-ink{fill:var(--text-secondary)}
#fs-ns2 /* an absence, #fs-ns2 drawn at the size the quantity would occupy if it existed */
.aperture{fill:none;stroke:var(--text-primary);stroke-width:1.5;stroke-dasharray:none}
#fs-ns2 .leader{stroke:var(--text-secondary);stroke-width:1;fill:none}

fs-gs.css:
#fs-gs /* The drawing is never scaled: fixed px width, #fs-gs no percentage cap, #fs-gs because
   a cap would quietly rescale the unit on a narrow screen. */
svg.draw{display:block;width:300px;height:auto}
#fs-gs svg.draw.hero{width:512px}
#fs-gs .c-con{fill:var(--consumption)}
#fs-gs /* household consumption, #fs-gs from F4 */
.c-gov{fill:var(--government)}
#fs-gs /* 3.12:1 light, #fs-gs 4.48:1 dark */
.c-inv{fill:var(--investment)}
#fs-gs i.c-con{background:var(--consumption)}
#fs-gs i.c-gov{background:var(--government)}
#fs-gs i.c-inv{background:var(--investment)}
#fs-gs /* F5 and F6b are not lattice figures: position on a common scale is the
   accurate encoding and the unit contract governs cells, #fs-gs not axes. */
.dot{stroke:var(--surface-1);stroke-width:2}
#fs-gs .grid{stroke:var(--gridline);stroke-width:1;fill:none}
#fs-gs .grid.zero{stroke:var(--baseline);stroke-width:1.5}
#fs-gs .axis{stroke:var(--baseline);stroke-width:1;fill:none}
#fs-gs .tk{fill:var(--text-secondary);font-size:11px;font-variant-numeric:tabular-nums}
#fs-gs .rowhit{fill:transparent}

fs-tv1.css:
#fs-tv1 .axis{stroke:var(--baseline);stroke-width:1;fill:none}
#fs-tv1 .gridl{stroke:var(--gridline);stroke-width:1;fill:none}
#fs-tv1 .tk{fill:var(--text-muted);font-size:11px;font-variant-numeric:tabular-nums;
    font-family:"InterVar","InterFallback",ui-sans-serif,system-ui,sans-serif}
#fs-tv1 .lb-s{fill:var(--text-secondary);font-size:10.5px;
    font-family:"InterVar","InterFallback",ui-sans-serif,system-ui,sans-serif}
#fs-tv1 .lb-p{fill:var(--text-primary);font-size:11.5px;font-weight:640;
    font-family:"InterVar","InterFallback",ui-sans-serif,system-ui,sans-serif}
#fs-tv1 .val{fill:var(--text-primary);font-size:12px;font-weight:680;font-variant-numeric:tabular-nums;
    font-family:"InterVar","InterFallback",ui-sans-serif,system-ui,sans-serif}
#fs-tv1 .big{fill:var(--text-primary);font-size:26px;font-weight:720;letter-spacing:-.02em;
    font-family:"InterVar","InterFallback",ui-sans-serif,system-ui,sans-serif}
#fs-tv1 /* Rule 2 made literal: an open mark, #fs-tv1 at full size, #fs-tv1 never faded. */
.opened{fill:none;stroke:var(--text-primary);stroke-width:2}
#fs-tv1 .ringed{stroke:var(--surface-1);stroke-width:2}
#fs-tv1 .dim{stroke:var(--text-primary);stroke-width:1.5;fill:none}
